/**
 * LiveBlade.js — Public API
 * -------------------------
 * The surface developers call from Blade templates.
 * Delegates all mechanics to formLogic (internal).
 *
 * Import chain:
 *   forms.js  →  form-logic.js  →  liveblade-responses.js
 *
 * @version 2.0.0
 * @license MIT
 */

import formLogic from './form-logic.js';

(function (global) {
    'use strict';

    const LiveBlade = {};

    // ── Delete ────────────────────────────────────────────────────────────────

    /**
     * Send a DELETE request for a loop-rendered row.
     * @param {string} deleteUrl
     * @returns {Promise<boolean>}
     *
     * @example
     * await LiveBlade.deleteItemInLoop('/promotions/5');
     */
    LiveBlade.deleteItemInLoop = function (deleteUrl) {
        return formLogic.loopDeleteForms(deleteUrl);
    };

    // ── Update ────────────────────────────────────────────────────────────────

    /**
     * PUT/PATCH a loop-rendered edit form.
     * @param {Object} data       FormData entries as a plain object; must include _method
     * @param {string} updateUrl
     * @returns {Promise<boolean>}
     *
     * @example
     * const data = Object.fromEntries(new FormData(form));
     * data._method = 'PUT';
     * await LiveBlade.editLoopForms(data, '/promotions/5');
     */
    LiveBlade.editLoopForms = function (data = {}, updateUrl) {
        return formLogic.loopUpdateForms(data, updateUrl);
    };

    // ── Create ────────────────────────────────────────────────────────────────

    /**
     * Submit a create/store form.
     * @param {Object} data   Must include routeName (_method optional, defaults POST)
     * @returns {Promise<boolean>}
     *
     * @example
     * const data = Object.fromEntries(new FormData(form));
     * data._method  = 'POST';
     * data.routeName = '/promotions';
     * await LiveBlade.submitFormItems(data);
     */
    LiveBlade.submitFormItems = function (data = {}) {
        return formLogic.submitFormEntities(data);
    };

    // ── Status toggle ─────────────────────────────────────────────────────────

    /**
     * POST a status update for a toggle switch.
     * @param {string} updateUrl
     * @param {0|1}    selectedStatus
     *
     * @example
     * LiveBlade.loopUpdateStatus('/promotions/5/status', 1);
     */
    LiveBlade.loopUpdateStatus = function (updateUrl, selectedStatus) {
        formLogic.loopUpdateStatusForms(updateUrl, selectedStatus);
    };

    // ── Image upload ──────────────────────────────────────────────────────────

    /**
     * Upload a single file.
     * @param {File}   file
     * @param {string} uploadRoute
     * @param {string} fileInputName   Server-side field name
     *
     * @example
     * const file = input.files[0];
     * LiveBlade.uploadImage(file, '/upload/avatar', 'avatar');
     */
    LiveBlade.uploadImage = function (file, uploadRoute, fileInputName) {
        formLogic.beginUploadImage(file, uploadRoute, fileInputName);
    };

    // ── Action-driven call ────────────────────────────────────────────────────

    /**
     * Fire a GET action URL (approve, activate, archive, etc.).
     * @param {string} elementUrl
     * @returns {Promise<boolean>}
     *
     * @example
     * await LiveBlade.actionDriven('/promotions/5/activate');
     */
    LiveBlade.actionDriven = function (elementUrl) {
        return formLogic.actionDrivenCall(elementUrl);
    };

    // ── Search ────────────────────────────────────────────────────────────────

    /**
     * Client-side table search (DOM filtering). Best for < 200 rows.
     * @param {string} inputId
     * @param {string} tableId
     */
    LiveBlade.searchTableItems = function (inputId, tableId) {
        formLogic.beginTableSearch(inputId, tableId);
    };

    /**
     * Server-side (DB) search with pagination support.
     * Hits searchUrl?q=…&page=… and re-renders the table body + pagination.
     *
     * @param {Object} opts
     * @param {string}   opts.inputId       id of the search <input>
     * @param {string}   opts.tableId       id of the <table>
     * @param {string}   opts.searchUrl     GET endpoint
     * @param {Function} opts.rowRenderer   fn(row) → '<tr>…</tr>' HTML string
     * @param {string}   [opts.paginationId]  id of a <div> for pagination links
     * @param {number}   [opts.debounceMs=350]
     *
     * @example
     * LiveBlade.serverSearch({
     *     inputId:      'searchInput',
     *     tableId:      'promotionsTable',
     *     searchUrl:    '/api/promotions/search',
     *     paginationId: 'promotionsPagination',
     *     rowRenderer: (row) => `
     *         <tr>
     *             <td>${row.name}</td>
     *             <td>${row.discount_value}</td>
     *         </tr>`,
     * });
     */
    LiveBlade.serverSearch = function (opts) {
        formLogic.beginServerSearch(opts);
    };

    /**
     * Client-side card/grid search.
     * @param {string} inputId
     * @param {string} cardSelector
     * @param {string} attributeName
     * @param {string} titleSelector
     */
    LiveBlade.searchCardItems = function (inputId, cardSelector, attributeName, titleSelector) {
        formLogic.beginCardSearch(inputId, cardSelector, attributeName, titleSelector);
    };

    // ── Table filter ──────────────────────────────────────────────────────────

    /**
     * Dropdown filter for a table.
     * @param {string} filterSelector
     * @param {string} tableSelector
     * @param {string} attribute
     */
    LiveBlade.setupTableFilter = function (filterSelector, tableSelector, attribute) {
        formLogic.beginTableFilter(filterSelector, tableSelector, attribute);
    };

    // ── Pagination (standalone) ───────────────────────────────────────────────

    /**
     * Render Bootstrap pagination links into a container.
     * Use when you manage the AJAX call yourself but want LiveBlade's
     * pagination UI.
     *
     * @param {string}   containerId
     * @param {Object}   paginationMeta   { current_page, last_page, from, to, total }
     * @param {Function} onPageClick      fn(pageNumber)
     *
     * @example
     * LiveBlade.renderPagination('myPager', response.pagination, page => {
     *     fetch(`/promotions?page=${page}`).then(...);
     * });
     */
    LiveBlade.renderPagination = function (containerId, paginationMeta, onPageClick) {
        formLogic._renderPagination(containerId, paginationMeta, onPageClick);
    };

    // ── Button loading state ──────────────────────────────────────────────────

    /**
     * Toggle a submit button between normal and loading states.
     * The button must contain two child spans:
     *   <span class="indicator-label">Save</span>
     *   <span class="indicator-progress" style="display:none">
     *       Please wait… <span class="spinner-border spinner-border-sm"></span>
     *   </span>
     *
     * @param {HTMLElement} button
     * @param {boolean}     isLoading
     */
    LiveBlade.toggleButtonLoading = function (button, isLoading) {
        if (!(button instanceof HTMLElement)) {
            console.warn('[LiveBlade] toggleButtonLoading: invalid element');
            return;
        }
        const label    = button.querySelector('.indicator-label');
        const progress = button.querySelector('.indicator-progress');

        if (isLoading) {
            button.disabled = true;
            if (label)    label.style.display    = 'none';
            if (progress) progress.style.display = 'inline';
        } else {
            button.disabled = false;
            if (label)    label.style.display    = 'inline';
            if (progress) progress.style.display = 'none';
        }
    };

    // ── Expose globally ───────────────────────────────────────────────────────
    global.LiveBlade = LiveBlade;

})(window);